def comb_sort(arr):
    gap = len(arr)
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink_factor)
        new_gap = max(1, gap)
        if new_gap < 1:
            sorted = True
        else:
            i = 0
            while i + new_gap < len(arr):
                if arr[i] > arr[i + new_gap]:
                    arr[i], arr[i + new_gap] = arr[i + new_gap], arr[i]
                i += 1

    # Final bubble sort pass to ensure the list is sorted
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            arr[i], arr[i + 1] = arr[i + 1], arr[i]

    return arr

