        else:
            swapped = False
            i = 0
            while i + new_gap < len(arr):
                if arr[i] > arr[i + new_gap]:
                    arr[i], arr[i + new_gap] = arr[i + new_gap], arr[i]
                    swapped = True
                i += 1
            if not swapped:
                sorted = True

    # Final bubble sort pass to ensure the list is sorted
