def eulerian_num(n, m):
    # Base case: if m is 0 or n, return 0
    if m == 0 or m == n:
        return 0
    # Base case: if m is 1 less than n, return n - 1
    elif m == n - 1:
        return n - 1
    # Recursive case: calculate Eulerian number using the formula
    else:
        return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m)

