def even_binomial_Coeff_Sum(N):
    # Helper function to calculate binomial coefficient using a dynamic programming approach
    def binomial_coefficient(n, k, memo):
        if k == 0 or k == n:
            return 1
        if (n, k) not in memo:
            memo[(n, k)] = binomial_coefficient(n - 1, k - 1, memo) + binomial_coefficient(n - 1, k, memo)
        return memo[(n, k)]

    # Calculate the sum of even index binomial coefficients
    sum_even = 0
    memo = {}
    for i in range(0, N + 1, 2):
        sum_even += binomial_coefficient(N, i, memo)
    return sum_even

